<script setup lang="ts">import { computed } from 'vue';import { useCalendarStore } from '../../stores/calendar.store';const c=useCalendarStore();const days=computed(()=>{const d=new Date(c.cursor),dow=(d.getDay()+6)%7;d.setDate(d.getDate()-dow);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return x})});function events(d:Date){return c.sortedEvents.filter(e=>new Date(e.start).toDateString()===d.toDateString())}</script><template><div class="week-grid"><section v-for="d in days" :key="d.toISOString()"><header><b>{{d.toLocaleDateString('it-IT',{weekday:'short'})}}</b><span>{{d.getDate()}}</span></header><article v-for="e in events(d)" :key="e.id"><small>{{e.allDay?'giorno':new Date(e.start).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}}</small><b>{{e.title}}</b></article></section></div></template><style scoped>.week-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:.45rem}.week-grid>section{min-height:390px;border:1px solid var(--glass-border);border-radius:14px;padding:.55rem}.week-grid header{display:flex;justify-content:space-between;text-transform:capitalize;color:var(--text-secondary);margin-bottom:.7rem}.week-grid article{display:grid;gap:.15rem;padding:.5rem;border-radius:9px;background:rgba(158,205,182,.1);margin-bottom:.4rem}.week-grid article small{color:var(--text-muted)}.week-grid article b{font-size:.76rem}@media(max-width:850px){.week-grid{grid-template-columns:1fr}.week-grid>section{min-height:auto}}</style>
